-- Recommended: #temp table, indexed, reused three times
SELECT CustomerID, OrderDate, TotalDue
INTO #RecentOrders
FROM Sales.SalesOrderHeader
WHERE OrderDate >= DATEADD(MONTH, -6, GETDATE());

CREATE INDEX IX_RecentOrders_CustomerID ON #RecentOrders (CustomerID);

-- Reference 1
SELECT CustomerID, COUNT(*) AS OrderCount FROM #RecentOrders GROUP BY CustomerID;
-- Reference 2
SELECT * FROM #RecentOrders WHERE TotalDue > 1000;
-- Reference 3
SELECT CustomerID, MAX(OrderDate) FROM #RecentOrders GROUP BY CustomerID;

DROP TABLE #RecentOrders;

