-- Masking policy: per-column, per-value
CREATE MASKING POLICY mask_cc AS (val STRING) RETURNS STRING ->
  CASE WHEN CURRENT_ROLE() IN ('FINANCE_ADMIN') THEN val ELSE 'XXXX-XXXX-XXXX-' || RIGHT(val, 4) END;
ALTER TABLE orders MODIFY COLUMN credit_card_number SET MASKING POLICY mask_cc;

-- Row access policy: per-row, decides inclusion, not content
CREATE ROW ACCESS POLICY region_filter AS (region STRING) RETURNS BOOLEAN ->
  EXISTS (SELECT 1 FROM region_access WHERE role_name = CURRENT_ROLE() AND allowed_region = region);
ALTER TABLE orders ADD ROW ACCESS POLICY region_filter ON (sales_region);

