    @Color NVARCHAR(50),
    @SortColumn NVARCHAR(50)
AS
BEGIN
    DECLARE @SQL NVARCHAR(MAX);
    SET @SQL = 'SELECT Name, Color, ListPrice FROM Production.Product WHERE Color = ''' 
