ALTER PROCEDURE usp_SearchProducts
    @Color NVARCHAR(50),
    @SortColumn NVARCHAR(50)
AS
BEGIN
    -- Validate the identifier against a fixed allow-list; it can never be parameterized
    IF @SortColumn NOT IN (N'Name', N'Color', N'ListPrice')
        SET @SortColumn = N'Name';

    DECLARE @SQL NVARCHAR(MAX) = N'SELECT Name, Color, ListPrice '
        + N'FROM Production.Product '
        + N'WHERE Color = @ColorParam '
        + N'ORDER BY ' + QUOTENAME(@SortColumn);

    EXEC sp_executesql @SQL, N'@ColorParam NVARCHAR(50)', @ColorParam = @Color;
END

-- BEFORE: inconsistent lock order causes the deadlock
-- usp_UpdateOrderStatus: Orders -> OrderDetails
-- usp_ApplyDiscount:     OrderDetails -> Orders

-- AFTER: both procedures agree on the same order
ALTER PROCEDURE usp_ApplyDiscount
    @OrderID INT, @DiscountPct DECIMAL(5,2)
AS
BEGIN
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;

    -- Touch Orders FIRST, matching usp_UpdateOrderStatus's order
    UPDATE Orders SET LastModified = SYSUTCDATETIME() WHERE OrderID = @OrderID;

    UPDATE OrderDetails
    SET UnitPrice = UnitPrice * (1 - @DiscountPct)
    WHERE OrderID = @OrderID;

    COMMIT TRANSACTION;
END

-- Before: row-by-row cursor, each UPDATE its own mini-operation
DECLARE @CustomerID INT;
DECLARE loyalty_cursor CURSOR FOR
    SELECT CustomerID FROM dbo.DailyPurchases WHERE PurchaseDate = @Today;
OPEN loyalty_cursor;
FETCH NEXT FROM loyalty_cursor INTO @CustomerID;
WHILE @@FETCH_STATUS = 0
BEGIN
    UPDATE dbo.Customer SET LoyaltyPoints = LoyaltyPoints + 10 WHERE CustomerID = @CustomerID;
    FETCH NEXT FROM loyalty_cursor INTO @CustomerID;
END
CLOSE loyalty_cursor; DEALLOCATE loyalty_cursor;

-- After: one set-based statement, processed as a single batch
UPDATE c
SET c.LoyaltyPoints = c.LoyaltyPoints + 10
FROM dbo.Customer c
JOIN dbo.DailyPurchases dp ON dp.CustomerID = c.CustomerID
WHERE dp.PurchaseDate = @Today;

-- Diagnose: check grants at every level, not just the table
SHOW GRANTS ON CATALOG sales_catalog;
SHOW GRANTS ON SCHEMA sales_catalog.reporting;
SHOW GRANTS ON TABLE sales_catalog.reporting.orders;

-- Likely missing grants -- add both:
GRANT USE CATALOG ON CATALOG sales_catalog TO `contractors`;
GRANT USE SCHEMA ON SCHEMA sales_catalog.reporting TO `contractors`;
-- Existing SELECT ON TABLE grant now becomes reachable.

CREATE FUNCTION region_row_filter(sales_region STRING) RETURNS BOOLEAN
RETURN
  is_account_group_member('unity_admins')  -- explicit admin exception
  OR EXISTS (
    SELECT 1 FROM region_access
    WHERE role_name = CURRENT_USER() AND region_access.sales_region = sales_region
  );

ALTER TABLE orders SET ROW FILTER region_row_filter ON (sales_region);

-- Check the policy's actual logic
