-- Check whether ANALYST inherits FINANCE_ADMIN through the hierarchy
SHOW GRANTS OF ROLE FINANCE_ADMIN;

-- If the policy uses IS_ROLE_IN_SESSION(), tighten it to CURRENT_ROLE():
CREATE OR REPLACE MASKING POLICY cc_full_redact AS (val STRING) RETURNS STRING ->
  CASE WHEN CURRENT_ROLE() IN ('FINANCE_ADMIN', 'PAYMENTS_OPS') THEN val
       ELSE 'XXXX-XXXX-XXXX-XXXX' END;

DECLARE @ProductAlternateKey NVARCHAR(25) = 'BK-M68B-42';
DECLARE @NewName NVARCHAR(50) = 'Mountain-200 Black, 42 (Revised)';
DECLARE @Now DATETIME = SYSUTCDATETIME();

BEGIN TRANSACTION;

-- 1. Expire the current row
UPDATE dbo.DimProduct
SET EndDate = @Now, Status = 'Expired'
WHERE ProductAlternateKey = @ProductAlternateKey
  AND Status = 'Current';

-- 2. Insert the new current row with a NEW surrogate key
INSERT INTO dbo.DimProduct
    (ProductAlternateKey, EnglishProductName, StartDate, EndDate, Status)
VALUES
    (@ProductAlternateKey, @NewName, @Now, NULL, 'Current');

COMMIT TRANSACTION;

-- Fact rows loaded before @Now still reference the OLD ProductKey
-- and will correctly show the old name in historical reports.

